package sfc

import (
	"bytes"

	"github.com/ethereum/go-ethereum/common/hexutil"
	"github.com/ethereum/go-ethereum/log"
)

// GetPatch7ContractBin returns the Cycle-162 reward-cursor SFC bytecode
// re-flashed by the SfcV2Patch7 upgrade. It is distinct from the historical
// Patch4/Patch5/Patch6 accessors so each sealed testnet re-flash remains
// reproducible, while fresh SfcV2 activations consume this bytecode through
// GetLatestContractBin().
//
// Cycle-162 source: VinuChain/vinuchain-lists contracts/vinuchain/SFC.sol.
// Compiled with solc 0.5.17+commit.d19bba13 --optimize --optimize-runs=10000
// --evm-version=istanbul.
//
// Delta from Cycle-162 orphan-stake bytecode (SfcV2Patch6): seeds
// stashedRewardsUntilEpoch[delegator][toValidatorID] = currentSealedEpoch on a
// delegator's first delegation in _rawDelegate (guarded by
// getStake[delegator][toValidatorID] == 0 && stashedRewardsUntilEpoch == 0), so
// the reward cursor for a post-genesis delegator starts at the validator's
// reward window rather than 0. Without the seed the cursor crawls forward at
// most 100 epochs per _stashRewards call through the all-zero-ARPT dead zone,
// making pendingRewards() over-report while claimRewards/restakeRewards revert
// "zero rewards". Forward-only and idempotent on networks that already activate
// the latest SFC bytecode at their first SfcV2 transition.
//
// Validity of the compiled asset is enforced at opera binary startup via
// EnforcePatch7StartupCheck.
func GetPatch7ContractBin() []byte {
	return patch7ContractBin
}

// EnforcePatch7StartupCheck validates the compiled-in Patch7 bytecode at
// binary startup. A build whose Patch7 bytes are placeholder, all zero, too
// short, or byte-identical to Patch5/Patch6 refuses to start rather than
// reaching the on-chain re-flash block with an invalid asset.
func EnforcePatch7StartupCheck() {
	if err := validatePatch7Bytecode(patch7ContractBin); err != nil {
		log.Crit("SfcV2Patch7 bytecode asset is invalid - the binary must not start with this build. Recompile SFC from vinuchain-lists and replace sfc_patch7_bytecode.go", "err", err)
	}
}

var patch7DeadbeefSentinel = []byte{0xde, 0xad, 0xbe, 0xef}

// patch7ContractBin is the deployed Cycle-162 reward-cursor runtime bytecode.
// The full hex string is a single-line literal to mirror the
// sfc_patch6_bytecode.go convention for patch6ContractBin.
//
// Size: 47,299 bytes. Hex-string sha256:
// d4e7addb12897c2db9ecf17b95bf1716d7e1c8f2a7974ec2f6fbe6b55adb5991
// Decoded-raw-bytes sha256:
// 2278d14607659004d78acb31ca5ebcd9119b31571d16bb42361b5423d4586219
var patch7ContractBin = hexutil.MustDecode("")

// minRealPatch7BytecodeLen is a lower bound on a legitimate compiled SFC. A real
// Cycle-162 SFC is ~47 KB; 10000 bytes rejects sentinel-sized placeholders while
// leaving head-room for plausible future compiles.
const minRealPatch7BytecodeLen = 10000

// validatePatch7Bytecode returns a non-nil error if the argument is not a
// plausible real compiled SFC, so neither EnforcePatch7StartupCheck nor any
// future release can ship the sentinel bytes in place of a real compile.
func validatePatch7Bytecode(code []byte) error {
	if len(code) == 0 {
		return errPatch7Empty
	}
	if len(code) < minRealPatch7BytecodeLen {
		return errPatch7TooShort
	}
	if len(code) >= len(patch7DeadbeefSentinel) && bytes.Equal(code[:len(patch7DeadbeefSentinel)], patch7DeadbeefSentinel) {
		return errPatch7Sentinel
	}
	allZero := true
	for _, b := range code {
		if b != 0 {
			allZero = false
			break
		}
	}
	if allZero {
		return errPatch7AllZero
	}
	if bytes.Equal(code, GetPatch5ContractBin()) {
		return errPatch7EqualsPatch5
	}
	if bytes.Equal(code, GetPatch6ContractBin()) {
		return errPatch7EqualsPatch6
	}
	return nil
}

type patch7Error string

func (e patch7Error) Error() string { return string(e) }

const (
	errPatch7Empty        patch7Error = "patch7 bytecode is empty"
	errPatch7TooShort     patch7Error = "patch7 bytecode shorter than minimum SFC size - placeholder not replaced"
	errPatch7Sentinel     patch7Error = "patch7 bytecode begins with deadbeef sentinel - placeholder not replaced"
	errPatch7AllZero      patch7Error = "patch7 bytecode is all zeros"
	errPatch7EqualsPatch5 patch7Error = "SfcV2Patch7 bytecode is byte-identical to Patch5 (Cycle-161) - the Patch7 re-flash would no-op on chain and the reward-cursor fix would not deploy"
	errPatch7EqualsPatch6 patch7Error = "SfcV2Patch7 bytecode is byte-identical to Patch6 (Cycle-162 orphan-stake) - the Patch7 re-flash would no-op on chain and the reward-cursor fix would not deploy"
)
